#!/usr/bin/env python3
from __future__ import annotations

import argparse
import base64
import datetime as dt
import importlib.util
import os
import py_compile
import shutil
import subprocess
import sys
from pathlib import Path

VERSION = "0.13.6"

MODIFIED_B64 = {'backend/app/services/vision_app/models.py': {'old': '',
                                               'new': ''},
 'backend/app/services/vision_app/repository.py': {'old': '',
                                                   'new': ''},
 'backend/app/services/vision_app/workspace_runtime.py': {'old': '',
                                                          'new': ''},
 'backend/app/services/vision_app/automation_manager.py': {'old': '',
                                                           'new': ''},
 'backend/app/api/v1/endpoints/vision_app_api.py': {'old': '',
                                                    'new': ''},
 'frontend/src/api/visionAppApi.ts': {'old': '',
                                      'new': ''},
 'frontend/src/Pages/ComputerVisionPage.tsx': {'old': '',
                                               'new': ''},
 'frontend/src/components/ComputerVision/IotDeclarationWorkspace.tsx': {'old': '',
                                                                        'new': ''},
 'frontend/src/components/ComputerVision/CameraDeclarationWorkspace.tsx': {'old': '',
                                                                           'new': ''},
 'frontend/src/components/ComputerVision/AutomationIdeWorkspace.tsx': {'old': '',
                                                                       'new': ''},
 'frontend/tools/generate_llm_context_map.py': {'old': '',
                                                'new': ''}}
CREATED_B64 = {'backend/tests/vision_app/test_vision_app_v1360.py': '',
 'frontend/docs/llm_context/updates/v1360_workspace_owned_io_camera.md': ''}

MODIFIED = {
    path: {
        "old": base64.b64decode(payload["old"]).decode("utf-8"),
        "new": base64.b64decode(payload["new"]).decode("utf-8"),
    }
    for path, payload in MODIFIED_B64.items()
}
CREATED = {
    path: base64.b64decode(payload).decode("utf-8")
    for path, payload in CREATED_B64.items()
}


def resolve_roots(frontend_arg: str | None, backend_arg: str | None):
    cwd = Path.cwd().resolve()
    fe_candidates = []
    be_candidates = []
    if frontend_arg:
        fe_candidates.append(Path(frontend_arg).expanduser().resolve())
    if backend_arg:
        be_candidates.append(Path(backend_arg).expanduser().resolve())
    fe_candidates += [cwd, cwd / "LambdaVisionSuper", cwd.parent / "LambdaVisionSuper"]
    be_candidates += [cwd, cwd / "LambdaVisionSuperBackEnd", cwd.parent / "LambdaVisionSuperBackEnd"]
    frontend = next((p for p in fe_candidates if (p / "src/Pages/ComputerVisionPage.tsx").exists() and (p / "src/components/ComputerVision/WorkspaceTabs.tsx").exists()), None)
    backend = next((p for p in be_candidates if (p / "app/services/vision_app/models.py").exists() and (p / "tests/vision_app").exists()), None)
    if frontend is None:
        raise RuntimeError("Cannot locate LambdaVisionSuper frontend. Use --frontend /path/to/LambdaVisionSuper")
    if backend is None:
        raise RuntimeError("Cannot locate LambdaVisionSuperBackEnd. Use --backend /path/to/LambdaVisionSuperBackEnd")
    return frontend, backend


def real_path(frontend: Path, backend: Path, virtual: str) -> Path:
    if virtual.startswith("frontend/"):
        return frontend / virtual[len("frontend/"):]
    if virtual.startswith("backend/"):
        return backend / virtual[len("backend/"):]
    raise ValueError(virtual)


def modified_state(path: Path, old: str, new: str) -> str:
    if not path.exists():
        return "MISSING"
    current = path.read_text(encoding="utf-8")
    if current == new:
        return "OK"
    if current == old:
        return "UPDATE"
    return "CONFLICT"


def created_state(path: Path, desired: str) -> str:
    if not path.exists():
        return "CREATE"
    return "OK" if path.read_text(encoding="utf-8") == desired else "CONFLICT"


def scan(frontend: Path, backend: Path):
    print("=" * 116)
    print("COMPUTER VISION V0.13.6 — WORKSPACE-OWNED CAMERA / IOT RESOURCES")
    print("=" * 116)
    print(f"Frontend : {frontend}")
    print(f"Backend  : {backend}")
    print()
    conflicts = 0
    for virtual, payload in MODIFIED.items():
        state = modified_state(real_path(frontend, backend, virtual), payload["old"], payload["new"])
        print(f"  [{state:12}] {virtual}")
        if state in {"CONFLICT", "MISSING"}:
            conflicts += 1
    for virtual, desired in CREATED.items():
        state = created_state(real_path(frontend, backend, virtual), desired)
        print(f"  [{state:12}] {virtual}")
        if state == "CONFLICT":
            conflicts += 1
    print()
    print("v0.13.6 contract:")
    print("  + WorkspaceDefinition owns its own IOT declarations and Camera declarations")
    print("  + fresh Workspace => iot.devices=[] and cameras.devices=[]")
    print("  + v<=6 global Camera/IOT declarations migrate ONLY into Workspace 1")
    print("  + Workspace 2+ never inherit Workspace 1 Camera/IOT declarations")
    print("  + Camera/IOT panels remount on workspace_id so local React selection/preview state cannot leak")
    print("  + Runtime + Automation Endpoint Registry project only the active Workspace Camera/IOT resources")
    print("  + Root program.iot/program.cameras remain compatibility mirrors, not resource owners")
    if conflicts:
        print()
        print(f"[WARN] {conflicts} conflict/base issue(s); apply will stop safely.")
    return 0


def preflight(frontend: Path, backend: Path):
    errors = []
    for virtual, payload in MODIFIED.items():
        state = modified_state(real_path(frontend, backend, virtual), payload["old"], payload["new"])
        if state not in {"UPDATE", "OK"}:
            errors.append(f"{virtual}: {state}")
    for virtual, desired in CREATED.items():
        state = created_state(real_path(frontend, backend, virtual), desired)
        if state not in {"CREATE", "OK"}:
            errors.append(f"{virtual}: {state}")
    if errors:
        raise RuntimeError("Safe update stopped:\n  - " + "\n  - ".join(errors))


def regenerate_context(frontend: Path, backend: Path):
    generator = frontend / "tools/generate_llm_context_map.py"
    cmd = [sys.executable, str(generator), "--frontend", str(frontend), "--backend", str(backend)]
    if "--output-dir" in generator.read_text(encoding="utf-8"):
        cmd.extend(["--output-dir", str(frontend / "docs/llm_context")])
    proc = subprocess.run(cmd, cwd=str(frontend), text=True, capture_output=True)
    if proc.returncode != 0:
        raise RuntimeError("Context generator failed:\n" + (proc.stdout + "\n" + proc.stderr).strip())
    if proc.stdout.strip():
        print(proc.stdout.strip())


def apply(frontend: Path, backend: Path):
    preflight(frontend, backend)
    stamp = dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_root = frontend / ".lambda_updater_backups" / f"computer_vision_v1360_{stamp}"
    backup_root.mkdir(parents=True, exist_ok=True)

    for virtual in [*MODIFIED.keys(), *CREATED.keys()]:
        path = real_path(frontend, backend, virtual)
        if path.exists():
            dst = backup_root / virtual
            dst.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(path, dst)

    for virtual, payload in MODIFIED.items():
        path = real_path(frontend, backend, virtual)
        desired = payload["new"]
        if path.read_text(encoding="utf-8") != desired:
            path.write_text(desired, encoding="utf-8")
            print(f"[WRITE] {virtual}")

    for virtual, desired in CREATED.items():
        path = real_path(frontend, backend, virtual)
        path.parent.mkdir(parents=True, exist_ok=True)
        if not path.exists() or path.read_text(encoding="utf-8") != desired:
            path.write_text(desired, encoding="utf-8")
            print(f"[WRITE] {virtual}")

    print("[INFO] Regenerating LLM context docs...")
    regenerate_context(frontend, backend)
    print(f"[OK] Backup: {backup_root}")
    print("Run verify next.")
    return 0


def typescript_transpile(frontend: Path):
    files = [
        frontend / "src/api/visionAppApi.ts",
        frontend / "src/Pages/ComputerVisionPage.tsx",
        frontend / "src/components/ComputerVision/IotDeclarationWorkspace.tsx",
        frontend / "src/components/ComputerVision/CameraDeclarationWorkspace.tsx",
        frontend / "src/components/ComputerVision/AutomationIdeWorkspace.tsx",
    ]
    code = r'''
const fs=require("fs");
const ts=require("typescript");
let bad=false;
for(const file of process.argv.slice(1)){
 const src=fs.readFileSync(file,"utf8");
 const r=ts.transpileModule(src,{
   fileName:file,
   reportDiagnostics:true,
   compilerOptions:{jsx:ts.JsxEmit.ReactJSX,target:ts.ScriptTarget.ES2020,module:ts.ModuleKind.ESNext}
 });
 const errs=(r.diagnostics||[]).filter(d=>d.category===ts.DiagnosticCategory.Error);
 if(errs.length){
   bad=true;
   console.error("TS_ERROR",file);
   for(const e of errs) console.error(ts.flattenDiagnosticMessageText(e.messageText,"\\n"));
 }
}
process.exit(bad?1:0);
'''
    env = dict(os.environ)
    npm_root = subprocess.run(["npm", "root", "-g"], text=True, capture_output=True)
    if npm_root.returncode == 0 and npm_root.stdout.strip():
        env["NODE_PATH"] = npm_root.stdout.strip() + (os.pathsep + env["NODE_PATH"] if env.get("NODE_PATH") else "")
    return subprocess.run(["node", "-e", code, *map(str, files)], cwd=str(frontend), env=env, text=True, capture_output=True)


def verify(frontend: Path, backend: Path, skip_build: bool = False):
    print("=" * 116)
    print("VERIFY COMPUTER VISION V0.13.6")
    print("=" * 116)
    failures = 0

    models = (backend / "app/services/vision_app/models.py").read_text(encoding="utf-8")
    repo = (backend / "app/services/vision_app/repository.py").read_text(encoding="utf-8")
    projection = (backend / "app/services/vision_app/workspace_runtime.py").read_text(encoding="utf-8")
    manager = (backend / "app/services/vision_app/automation_manager.py").read_text(encoding="utf-8")
    api = (backend / "app/api/v1/endpoints/vision_app_api.py").read_text(encoding="utf-8")
    page = (frontend / "src/Pages/ComputerVisionPage.tsx").read_text(encoding="utf-8")
    ide = (frontend / "src/components/ComputerVision/AutomationIdeWorkspace.tsx").read_text(encoding="utf-8")
    ts_api = (frontend / "src/api/visionAppApi.ts").read_text(encoding="utf-8")

    checks = [
        ("Program schema v7", "version: int = 7" in models),
        ("Workspace owns IOT", "iot: IotDeclarationConfig" in models),
        ("Workspace owns Camera declarations", "cameras: CameraDeclarationConfig" in models),
        ("Legacy migration only seeds Workspace 1", "if index == 0 else {\"devices\": []}" in repo),
        ("Save resolves camera inside each Workspace", "workspace.cameras.devices" in repo and "declaration from another Workspace is never a valid fallback" in repo),
        ("Runtime projection includes Workspace IOT/Camera", "payload['iot'] = dump(workspace.iot)" in projection and "payload['cameras'] = dump(workspace.cameras)" in projection),
        ("Automation catalog projects active Workspace", "program = self._active_program(self.repository.get(program_id))" in manager),
        ("Automation preview projects unsaved active Workspace", "preview_program = projected_program(program, workspace)" in api),
        ("Frontend Workspace type owns resources", "iot:IotDeclarationConfig; cameras:CameraDeclarationConfig" in ts_api),
        ("Fresh Workspace starts hardware-empty", "iot:{devices:[]}" in page and "cameras:{devices:[]}" in page),
        ("Camera panel reads active Workspace", "config={activeWorkspace.cameras}" in page and "key={`camera-${activeWorkspace.workspace_id}`}" in page),
        ("IOT panel reads active Workspace", "config={activeWorkspace.iot}" in page and "key={`iot-${activeWorkspace.workspace_id}`}" in page),
        ("No program-global Camera list in ComputerVisionPage", "program.cameras.devices" not in page),
        ("Automation IDE counts active Workspace resources", "activeWorkspace?.iot.devices" in ide and "activeWorkspace?.cameras.devices" in ide),
        ("v0.13.6 regression test installed", (backend / "tests/vision_app/test_vision_app_v1360.py").exists()),
        ("v0.13.6 handoff installed", (frontend / "docs/llm_context/updates/v1360_workspace_owned_io_camera.md").exists()),
    ]
    for label, ok in checks:
        print(f"[{'OK' if ok else 'FAIL'}] {label}")
        failures += 0 if ok else 1

    py_files = [
        backend / "app/services/vision_app/models.py",
        backend / "app/services/vision_app/repository.py",
        backend / "app/services/vision_app/workspace_runtime.py",
        backend / "app/services/vision_app/automation_manager.py",
        backend / "app/api/v1/endpoints/vision_app_api.py",
        backend / "tests/vision_app/test_vision_app_v1360.py",
        frontend / "tools/generate_llm_context_map.py",
    ]
    syntax_bad = []
    for path in py_files:
        try:
            py_compile.compile(str(path), doraise=True)
        except Exception as exc:
            syntax_bad.append(f"{path.name}: {exc}")
    if syntax_bad:
        print("[FAIL] Python syntax")
        for issue in syntax_bad:
            print("  -", issue)
        failures += len(syntax_bad)
    else:
        print("[OK] Python syntax")

    ts = typescript_transpile(frontend)
    ts_text = (ts.stdout + "\n" + ts.stderr).strip()
    if ts.returncode == 0:
        print("[OK] TypeScript syntax/transpile")
    elif "Cannot find module 'typescript'" in ts_text or "MODULE_NOT_FOUND" in ts_text:
        print("[SKIP] TypeScript module unavailable to Node")
    else:
        print("[FAIL] TypeScript syntax/transpile")
        print(ts_text)
        failures += 1

    if importlib.util.find_spec("pytest") is not None and (backend / "tests/vision_app").exists():
        full_ready = (backend / "app/core").exists() and (backend / "app/services/vision_labs").exists()
        targets = ["tests/vision_app"] if full_ready else ["tests/vision_app/test_vision_app_v1360.py"]
        proc = subprocess.run([sys.executable, "-m", "pytest", "-q", *targets], cwd=str(backend), text=True, capture_output=True)
        if proc.returncode == 0:
            print("[OK] Vision App regression tests")
            if proc.stdout.strip():
                print(proc.stdout.strip())
        else:
            print("[FAIL] Vision App regression tests")
            print((proc.stdout + "\n" + proc.stderr).strip())
            failures += 1
    else:
        print("[SKIP] pytest unavailable")

    if not skip_build and (frontend / "package.json").exists() and (frontend / "node_modules").exists():
        proc = subprocess.run(["npm", "run", "build"], cwd=str(frontend))
        if proc.returncode == 0:
            print("[OK] Frontend npm build")
        else:
            print("[FAIL] Frontend npm build")
            failures += 1
    else:
        print("[SKIP] Frontend npm build")

    try:
        regenerate_context(frontend, backend)
        print("[OK] LLM context regeneration")
    except Exception as exc:
        print(f"[FAIL] Context regeneration: {exc}")
        failures += 1

    if failures:
        print(f"[FAIL] v0.13.6 verification finished with {failures} issue(s).")
        return 1
    print("[OK] Computer Vision v0.13.6 Workspace-owned Camera/IOT isolation verified.")
    return 0


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("command", choices=["scan", "apply", "verify"])
    parser.add_argument("--frontend")
    parser.add_argument("--backend")
    parser.add_argument("--skip-build", action="store_true")
    args = parser.parse_args()
    try:
        frontend, backend = resolve_roots(args.frontend, args.backend)
        if args.command == "scan":
            return scan(frontend, backend)
        if args.command == "apply":
            return apply(frontend, backend)
        return verify(frontend, backend, skip_build=args.skip_build)
    except Exception as exc:
        print(f"[ERROR] {exc}")
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
